#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Assistant and AI connections setup, one stage at a time (docs/terraform.md,
# "Assistant and AI connections", has the runbook this follows):
#
#   scripts/assistant-setup.sh dev              dev workspace, dev key, dev agent into .env
#   scripts/assistant-setup.sh eval             eval workspace, eval key into GitHub and .env.eval
#   scripts/assistant-setup.sh prod             prod workspace, secrets, agent, webhook, OTel, preview
#   scripts/assistant-setup.sh required-check   assistant-eval as a required check on main
#   scripts/assistant-setup.sh launch           texts, notice email, AI connections, then the Assistant
#
# Every write (a file, a GitHub setting or secret, Secrets Manager, terraform
# apply) waits for a yes. Keys are read from 1Password into a variable, checked
# for their prefix and only then used, so a failed read never stores an empty
# secret; none is printed. An op:// path can't hold the parentheses in item
# titles like "(prod)", so items are looked up by title and read by id.

REPO="Daniel88dev/flexi-day-be"
FE_REPO="Daniel88dev/flexi-day"
VAULT="Development"
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
TF_DIR="$ROOT/terraform"
TFVARS="$TF_DIR/terraform.tfvars"
FE_TF_DIR="${FE_TERRAFORM_DIR:-$ROOT/../flexi-day/terraform}"
CONSOLE="https://console.anthropic.com"
WEBHOOK_URL="https://api.flexi-day.com/api/webhooks/anthropic"
EVAL_ENVIRONMENT="assistant-eval"
cd "$ROOT"

# bash -x would print the keys.
set +x

skip() {
  SKIPPED+=("$1")
  warn "skipped: $1"
}

need_tool() {
  command -v "$1" >/dev/null 2>&1 && return 0
  warn "$1 is not installed"
  return 1
}

# op_credential TITLE PREFIX VAR reads the credential field of TITLE into VAR,
# by id, and fails unless it starts with PREFIX.
op_credential() {
  local title="$1" prefix="$2" var="$3" id value
  need_tool op && need_tool jq || return 1
  id="$(op item get "$title" --vault "$VAULT" --format json 2>/dev/null | jq -r '.id // empty')" || id=""
  if [[ -z "$id" ]]; then
    warn "no item \"$title\" in the $VAULT vault"
    return 1
  fi
  if ! value="$(op read "op://$VAULT/$id/credential" 2>/dev/null)" || [[ -z "$value" ]]; then
    warn "could not read the credential of \"$title\""
    return 1
  fi
  if [[ "$value" != "$prefix"* || "$value" == *[[:space:]]* ]]; then
    warn "\"$title\" does not hold a $prefix value"
    return 1
  fi
  printf -v "$var" '%s' "$value"
  printf '  %s✓ read%s "%s" (%s…)\n' "$GREEN" "$RESET" "$title" "$prefix"
}

# env_secret ENVIRONMENT NAME VALUE sets a secret of a GitHub environment on REPO.
env_secret() {
  local environment="$1" name="$2" value="$3"
  if ! need_tool gh || ! gh auth status >/dev/null 2>&1; then
    skip "GitHub secret $name in $environment (gh not ready)"
    return 0
  fi
  if printf '%s' "$value" | gh secret set "$name" --env "$environment" --repo "$REPO" >/dev/null; then
    WRITTEN_SECRET+=("$environment/$name")
    printf '  %s✓ set%s %s in the %s environment\n' "$GREEN" "$RESET" "$name" "$environment"
  else
    skip "GitHub secret $name in $environment (gh secret set failed)"
  fi
}

# write_tfvar KEY HCL upserts `KEY = HCL` in terraform.tfvars.
write_tfvar() {
  local key="$1" value="$2" tmp
  if [[ ! -f "$TFVARS" ]]; then
    skip "$key in terraform.tfvars (no $TFVARS)"
    return 0
  fi
  if grep -qE "^${key}[[:space:]]*=[[:space:]]*\[[^]]*$" "$TFVARS"; then
    skip "$key in terraform.tfvars spans several lines; set it to $value by hand"
    return 0
  fi
  tmp=$(mktemp)
  grep -vE "^${key}[[:space:]]*=" "$TFVARS" > "$tmp" || true
  printf '%s = %s\n' "$key" "$value" >> "$tmp"
  cat "$tmp" > "$TFVARS"
  rm -f "$tmp"
  printf '  %s✓ wrote%s %s = %s → terraform.tfvars\n' "$GREEN" "$RESET" "$key" "$value"
}

current_tfvar() {
  [[ -f "$TFVARS" ]] || return 0
  grep -E "^${1}[[:space:]]*=" "$TFVARS" | tail -n1 | sed -E 's/^[^=]*=[[:space:]]*//' || true
}

# tf_apply DIR LABEL plans DIR into a temporary file, shows it, and applies that
# exact plan only on a yes. The plan file holds secret values, so it is deleted.
tf_apply() {
  local dir="$1" label="$2" plan_dir
  if ! need_tool terraform || [[ ! -d "$dir" ]]; then
    skip "terraform apply for $label (no terraform or no $dir)"
    return 0
  fi
  plan_dir=$(mktemp -d)
  say "Planning $label. Nothing changes until you confirm the apply."
  if ! terraform -chdir="$dir" plan -input=false -out="$plan_dir/plan"; then
    rm -rf "$plan_dir"
    skip "terraform apply for $label (the plan failed; fix it and re-run this stage)"
    return 0
  fi
  if confirm "Apply this plan to $label?"; then
    if terraform -chdir="$dir" apply -input=false "$plan_dir/plan"; then
      printf '  %s✓ applied%s %s\n' "$GREEN" "$RESET" "$label"
    else
      skip "terraform apply for $label (the apply failed)"
    fi
  else
    skip "terraform apply for $label"
  fi
  rm -rf "$plan_dir"
}

# provision KEY runs assistant:provision against the workspace of KEY with the
# production model defaults, and reads the two ids it prints into
# PROVISIONED_AGENT_ID and PROVISIONED_ENVIRONMENT_ID.
provision() {
  local key="$1" output
  PROVISIONED_AGENT_ID=""
  PROVISIONED_ENVIRONMENT_ID=""
  # Empty values beat .env (dotenv never overrides), so the agent gets the
  # production model and effort rather than whatever .env holds.
  if ! output="$(ANTHROPIC_API_KEY="$key" ASSISTANT_MODEL="" ASSISTANT_EFFORT="" \
    ASSISTANT_SCREEN_MODEL="" pnpm run --silent assistant:provision)"; then
    warn "assistant:provision failed"
    return 1
  fi
  PROVISIONED_AGENT_ID="$(printf '%s\n' "$output" | sed -n 's/^ASSISTANT_AGENT_ID=//p')"
  PROVISIONED_ENVIRONMENT_ID="$(printf '%s\n' "$output" | sed -n 's/^ASSISTANT_ENVIRONMENT_ID=//p')"
  printf '%s\n' "$output" | grep -v '^ASSISTANT_' | while read -r line; do note "$line"; done || true
  if [[ "$PROVISIONED_AGENT_ID" != agent_* || "$PROVISIONED_ENVIRONMENT_ID" != env_* ]]; then
    warn "assistant:provision printed no agent or environment id"
    return 1
  fi
  say "Agent:       $PROVISIONED_AGENT_ID"
  say "Environment: $PROVISIONED_ENVIRONMENT_ID"
}

slot_exists() {
  aws secretsmanager describe-secret --secret-id "$1" --region eu-central-1 >/dev/null 2>&1
}

# ── dev ──────────────────────────────────────────────────────────────────────

stages_dev() {
  local key=""
  TOTAL_STAGES=3
  banner "Assistant setup: dev"

  stage "The flexi-day-dev workspace"
  open_url "$CONSOLE/settings/workspaces"
  step "Open the workspace flexi-day-dev. It already exists; create it only if it doesn't."
  step "Check its spend limit: \$20 a month, with an email notification at \$10."
  note "That is the current budget, kept low while the Assistant is built. Raising it is"
  note "your decision; leave it as it is unless you mean to."
  step "Anyone working on the Assistant may be a member of this workspace."
  pause "Press Enter once the workspace and its limits look right."

  stage "The dev key"
  open_url "$CONSOLE/settings/keys"
  step "If 1Password has no \"Flexi Day Anthropic API key (dev)\" yet: create a key in"
  step "flexi-day-dev and save it in the $VAULT vault as an API Credential with that"
  step "title, the key in its credential field."
  pause "Press Enter once the item is in 1Password."
  if op_credential "Flexi Day Anthropic API key (dev)" "sk-ant-" key; then
    if confirm "Write it to .env as ANTHROPIC_API_KEY?"; then
      write_env ANTHROPIC_API_KEY "$key"
    else
      skip "ANTHROPIC_API_KEY in .env"
    fi
  else
    skip "the dev key (fix the 1Password item and re-run this stage)"
  fi

  stage "The dev agent and environment"
  say "pnpm run assistant:provision creates the agent and the environment named"
  say "flexi-day-assistant in flexi-day-dev, or finds them if they exist. It makes no"
  say "model call."
  if [[ -z "$key" ]]; then
    skip "assistant:provision for dev (no dev key)"
  elif confirm "Run assistant:provision against flexi-day-dev?"; then
    if provision "$key" && confirm "Write both ids to .env?"; then
      write_env ASSISTANT_AGENT_ID "$PROVISIONED_AGENT_ID"
      write_env ASSISTANT_ENVIRONMENT_ID "$PROVISIONED_ENVIRONMENT_ID"
    else
      skip "the dev ids in .env"
    fi
  else
    skip "assistant:provision for dev"
  fi
  note "ASSISTANT_DRIVER stays fake in .env. Set it to managed only for a session that"
  note "needs the real agent; every turn then spends from the \$20 dev budget."
  pause
  unset key
  finish
}

# ── eval ─────────────────────────────────────────────────────────────────────

stages_eval() {
  local key=""
  TOTAL_STAGES=3
  banner "Assistant setup: eval"

  stage "The flexi-day-eval workspace"
  open_url "$CONSOLE/settings/workspaces"
  step "Open the workspace flexi-day-eval. It already exists; create it only if it doesn't."
  step "Check its spend limit: \$20 a month, with an email notification at \$10."
  note "That is the current budget. The full eval suite and its baseline need more;"
  note "raising the limit is your decision, made in the Console when you want it."
  pause "Press Enter once the workspace and its limits look right."

  stage "The eval key in GitHub"
  step "1Password needs \"Flexi Day Anthropic API key (eval)\" in the $VAULT vault: an"
  step "API Credential with a flexi-day-eval key in its credential field."
  pause "Press Enter once it is there."
  if ! op_credential "Flexi Day Anthropic API key (eval)" "sk-ant-" key; then
    skip "the eval key (fix the 1Password item and re-run this stage)"
  elif ! need_tool gh || ! gh auth status >/dev/null 2>&1; then
    skip "the $EVAL_ENVIRONMENT environment (gh not ready)"
  else
    if gh api "repos/$REPO/environments/$EVAL_ENVIRONMENT" >/dev/null 2>&1; then
      say "The $EVAL_ENVIRONMENT environment exists on $REPO."
    elif confirm "Create the $EVAL_ENVIRONMENT environment on $REPO (no reviewers, any branch)?"; then
      if gh api -X PUT "repos/$REPO/environments/$EVAL_ENVIRONMENT" >/dev/null; then
        printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$EVAL_ENVIRONMENT"
      else
        skip "the $EVAL_ENVIRONMENT environment (gh api failed)"
      fi
    fi
    if confirm "Set ANTHROPIC_EVAL_API_KEY in the $EVAL_ENVIRONMENT environment?"; then
      env_secret "$EVAL_ENVIRONMENT" ANTHROPIC_EVAL_API_KEY "$key"
    else
      skip "ANTHROPIC_EVAL_API_KEY in $EVAL_ENVIRONMENT"
    fi
  fi

  stage "The eval key locally"
  say "pnpm run eval reads the key from .env.eval, which git ignores."
  if [[ -z "$key" ]]; then
    skip "ANTHROPIC_EVAL_API_KEY in .env.eval (no eval key)"
  elif confirm "Write it to .env.eval?"; then
    ENV_FILE=".env.eval"
    write_env ANTHROPIC_EVAL_API_KEY "$key"
    ENV_FILE=".env"
  else
    skip "ANTHROPIC_EVAL_API_KEY in .env.eval"
  fi
  unset key
  pause
  finish
}

# ── prod ─────────────────────────────────────────────────────────────────────

stages_prod() {
  # secret is filled by op_credential through printf -v, only to check it before put-secret.sh.
  # shellcheck disable=SC2034
  local key="" secret="" org_id=""
  TOTAL_STAGES=9
  banner "Assistant setup: prod"

  stage "Dark deploy and the empty slots"
  say "Both repos deploy with assistant_enabled and ai_connections_enabled false and an"
  say "empty ai_preview_organization_ids. Both Terraform roots are applied: the backend"
  say "creates the two Anthropic slots, the frontend the managed headers policy."
  if need_tool aws && slot_exists flexi-day-be-production-anthropic-api-key &&
    slot_exists flexi-day-be-production-anthropic-webhook-secret; then
    say "Both Anthropic slots exist."
  else
    warn "The Anthropic slots are missing (or aws can't see them)."
    if confirm "Plan and apply the backend Terraform now?"; then
      tf_apply "$TF_DIR" "the backend (flexi-day-be)"
    else
      skip "the backend apply"
    fi
  fi
  if confirm "Plan and apply the frontend Terraform (the managed headers policy) now?"; then
    tf_apply "$FE_TF_DIR" "the frontend (flexi-day)"
  fi
  pause

  stage "The flexi-day-prod workspace"
  open_url "$CONSOLE/settings/workspaces"
  step "Create the workspace flexi-day-prod in the existing organization."
  step "Spend limit: \$200 a month. Email notification at \$100."
  step "Members: you alone. The session viewer shows every transcript to each"
  step "Developer and Admin, so nobody else joins this workspace."
  step "Billing: credit auto-reload on for the organization."
  pause "Press Enter once that is done."
  if ! confirm "Are you the only member of flexi-day-prod?"; then
    warn "Remove the other members before any real chat reaches this workspace."
    SKIPPED+=("flexi-day-prod members")
  fi

  stage "The prod key"
  open_url "$CONSOLE/settings/keys"
  step "Create a key in flexi-day-prod. Save it in the $VAULT vault as an API Credential"
  step "titled \"Flexi Day Anthropic API key (prod)\", the key in its credential field."
  pause "Press Enter once it is in 1Password."
  if op_credential "Flexi Day Anthropic API key (prod)" "sk-ant-" key; then
    if confirm "Upload it to Secrets Manager with put-secret.sh anthropic-api-key?"; then
      terraform/scripts/put-secret.sh anthropic-api-key || skip "put-secret.sh anthropic-api-key"
    else
      skip "put-secret.sh anthropic-api-key"
    fi
  else
    skip "the prod key (fix the 1Password item and re-run this stage)"
  fi

  stage "The prod agent and environment"
  say "pnpm run assistant:provision creates flexi-day-assistant in flexi-day-prod, or"
  say "finds it, with the production model. Each deploy then keeps it current."
  if [[ -z "$key" ]]; then
    skip "assistant:provision for prod (no prod key)"
  elif confirm "Run assistant:provision against flexi-day-prod?"; then
    if provision "$key" && confirm "Write both ids to terraform.tfvars?"; then
      write_tfvar assistant_agent_id "\"$PROVISIONED_AGENT_ID\""
      write_tfvar assistant_environment_id "\"$PROVISIONED_ENVIRONMENT_ID\""
    else
      skip "the prod ids in terraform.tfvars"
    fi
  else
    skip "assistant:provision for prod"
  fi
  unset key
  pause

  stage "The webhook"
  open_url "$CONSOLE"
  step "Switch to flexi-day-prod and find its webhook settings."
  step "Add an endpoint: $WEBHOOK_URL"
  step "Subscribe it to session.status_idled only."
  step "Copy its signing secret (whsec_...). Save it in the $VAULT vault as an API"
  step "Credential titled \"Flexi Day Anthropic webhook secret (prod)\", in its credential field."
  note "The route answers 404 until the preview apply in the last stage, so a test"
  note "delivery fails until then. Send one again after it."
  pause "Press Enter once the secret is in 1Password."
  if op_credential "Flexi Day Anthropic webhook secret (prod)" "whsec_" secret; then
    if confirm "Upload it with put-secret.sh anthropic-webhook-secret?"; then
      terraform/scripts/put-secret.sh anthropic-webhook-secret ||
        skip "put-secret.sh anthropic-webhook-secret"
    else
      skip "put-secret.sh anthropic-webhook-secret"
    fi
  else
    skip "the webhook secret (fix the 1Password item and re-run this stage)"
  fi
  unset secret

  stage "OpenTelemetry to Sentry"
  say "Managed Agents can send its own spans to Sentry, nested under the backend's"
  say "traces (T-727's spike kept the destination: Sentry sends one traceparent per call)."
  if confirm "Set up the OTel destination now?"; then
    open_url "https://sentry.io/settings/projects/"
    step "In the flexi-day-be project: Settings > Client Keys (DSN). Copy the OTLP"
    step "endpoint and its authentication header."
    open_url "$CONSOLE"
    step "In flexi-day-prod, add an OpenTelemetry destination with that endpoint."
    step "Content: Metadata only. Never full content: transcripts must not reach Sentry."
    step "Leave flexi-day-dev and flexi-day-eval without one."
    pause "Press Enter once that is done."
  else
    skip "the OTel destination"
  fi

  stage "Sentry's pay-as-you-go budget"
  open_url "https://sentry.io/settings/billing/overview/"
  step "If the organization has no pay-as-you-go budget, set one of \$10 a month."
  step "Leave an existing budget as it is."
  pause "Press Enter once that is done."

  stage "Preview on your own organization"
  say "Your organization gets both features in production while the switches stay off."
  say "The plan reads both slots and fails if either is empty or holds the wrong kind"
  say "of value; the apply wires the secrets and the ids into App Runner."
  note "Current list: $(current_tfvar ai_preview_organization_ids)"
  ask org_id "Your organization's id (a UUID, from the app's organization settings URL):" || true
  if [[ ! "$org_id" =~ ^[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$ ]]; then
    skip "the preview list (\"$org_id\" is not an organization id)"
  elif confirm "Set ai_preview_organization_ids = [\"$org_id\"] in terraform.tfvars?"; then
    write_tfvar ai_preview_organization_ids "[\"$org_id\"]"
    tf_apply "$TF_DIR" "the backend (flexi-day-be)"
    step "Send a test delivery from the Console's webhook page, then open the Assistant"
    step "on www.flexi-day.com as a member of your organization."
    pause
  else
    skip "the preview list"
  fi

  stage "Sentry alerts and the dashboard"
  say "The signals exist once the deployment above is live. Every threshold is in"
  say "docs/terraform.md, Assistant and AI connections > Monitoring."
  open_url "https://sentry.io/issues/alerts/rules/"
  step "In the flexi-day-be project, add one monitor per row of the Monitoring table,"
  step "with the signal, window and threshold it names, notifying you by email."
  step "Metric monitors: assistant.cost_usd (sum over 1 day above 30),"
  step "assistant.screen_failed (5 in 15 min), assistant.session_error (3 in 15 min),"
  step "assistant.webhook_rejected (10 in 1 h)."
  step "Log monitors, any occurrence: assistant.reconcile_drift, assistant.webhook_missed,"
  step "session.budget_reached, agent.thread_context_compacted, assistant.provider_refused."
  step "Check that the existing high-priority alert covers /api/webhooks/anthropic errors."
  open_url "https://sentry.io/dashboards/"
  step "Add the dashboard \"Assistant and AI connections\" with the widgets the runbook lists."
  step "It notifies nobody: the two limit-reached logs are for reading, not paging."
  pause "Press Enter once the monitors and the dashboard exist."
  finish
}

# ── required-check ───────────────────────────────────────────────────────────

stages_required_check() {
  local checks=""
  TOTAL_STAGES=2
  banner "Assistant setup: required-check"

  stage "The eval check on main"
  say "assistant-eval becomes required only once its workflow runs on main."
  if ! need_tool gh || ! gh auth status >/dev/null 2>&1; then
    skip "the required check (gh not ready)"
    finish
    return 0
  fi
  checks="$(gh api "repos/$REPO/commits/main/check-runs" --jq '.check_runs[].name' 2>/dev/null || true)"
  if ! grep -qx "assistant-eval" <<<"$checks"; then
    warn "main's latest commit has no assistant-eval check run yet. Stop here and"
    warn "re-run this stage once the eval workflow is on main."
    SKIPPED+=("assistant-eval as a required check (not on main yet)")
    pause
    finish
    return 0
  fi
  say "main runs assistant-eval."
  pause

  stage "Require it"
  open_url "https://github.com/$REPO/settings/rules"
  step "Open the \"protected main\" ruleset."
  step "Under Require status checks to pass, add assistant-eval. Save."
  pause "Press Enter once it is saved."
  if gh api "repos/$REPO/rules/branches/main" \
    --jq '.[] | select(.type == "required_status_checks") | .parameters.required_status_checks[].context' \
    2>/dev/null | grep -qx "assistant-eval"; then
    say "main now requires assistant-eval."
  else
    warn "main does not list assistant-eval as required yet."
    SKIPPED+=("assistant-eval as a required check")
  fi
  pause
  finish
}

# ── launch ───────────────────────────────────────────────────────────────────

# notice_env_url prints the production DATABASE URL with the RDS CA pinned, as
# scripts/db-migrate.sh builds it. The caller keeps it in a variable, never on a
# command line.
notice_env_url() {
  local url ca_dir ca_path sep="?"
  need_tool aws || return 1
  url="$(aws secretsmanager get-secret-value --secret-id flexi-day-be-production-database-url \
    --region eu-central-1 --query SecretString --output text 2>/dev/null)" || return 1
  [[ "$url" == postgres* ]] || return 1
  ca_dir="${XDG_CACHE_HOME:-$HOME/.cache}/flexi-day"
  ca_path="$ca_dir/rds-global-bundle.pem"
  if [[ ! -s "$ca_path" ]]; then
    mkdir -p "$ca_dir"
    curl -fsS -o "$ca_path" https://truststore.pki.rds.amazonaws.com/global/global-bundle.pem ||
      return 1
  fi
  [[ "$url" == *\?* ]] && sep="&"
  printf '%s' "${url}${sep}sslmode=verify-full&sslrootcert=${ca_path}"
}

# subprocessor_notice ARG runs the notice command against production: its
# database and the prod SES template. The URL reaches pnpm through the
# environment only. The empty DEV_TOOLS_ENABLED beats .env (dotenv never
# overrides), since dev tools refuse to boot against a database that isn't local.
subprocessor_notice() {
  DATABASE="$PROD_DATABASE" DEV_TOOLS_ENABLED="" \
    EMAIL_TEMPLATE_STAGE=prod EMAIL_FROM=no-reply@flexi-day.com \
    SES_CONFIGURATION_SET=flexi-day-emails-production AWS_REGION=eu-central-1 \
    pnpm run --silent subprocessor-notice "$1"
}

stages_launch() {
  local sent_at="" sent_epoch now_epoch days day0="" PROD_DATABASE="" notice_status=0
  TOTAL_STAGES=4
  banner "Assistant setup: launch"

  stage "Day 0: publish the texts"
  say "The legal pages carry the AI wording only in a build with NEXT_PUBLIC_AI_TEXTS_PUBLISHED"
  say "set, and that date becomes their \"Last updated\" date. The Privacy banner starts on the"
  say "same day, so the next stage reuses it."
  ask day0 "Day 0 (YYYY-MM-DD), usually today:" || true
  if [[ ! "$day0" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then
    skip "Day 0 (no date given)"
    finish
    return 0
  fi
  note "NEXT_PUBLIC_AI_TEXTS_PUBLISHED on $FE_REPO is now \"$(gh variable get NEXT_PUBLIC_AI_TEXTS_PUBLISHED --repo "$FE_REPO" 2>/dev/null || true)\"."
  if confirm "Set NEXT_PUBLIC_AI_TEXTS_PUBLISHED = $day0 on $FE_REPO?"; then
    if gh variable set NEXT_PUBLIC_AI_TEXTS_PUBLISHED --repo "$FE_REPO" --body "$day0" >/dev/null; then
      printf '  %s✓ set%s NEXT_PUBLIC_AI_TEXTS_PUBLISHED on %s\n' "$GREEN" "$RESET" "$FE_REPO"
    else
      skip "NEXT_PUBLIC_AI_TEXTS_PUBLISHED on $FE_REPO (gh variable set failed)"
    fi
  else
    skip "NEXT_PUBLIC_AI_TEXTS_PUBLISHED = $day0 on $FE_REPO"
  fi
  open_url "https://github.com/$FE_REPO/actions/workflows/ci.yml?query=branch%3Amain"
  step "Re-run the latest CI run on main, so the deploy builds the pages with the date."
  step "Then check https://www.flexi-day.com/privacy/ says \"Last updated\" on $day0 and has"
  step "the \"AI connections\" section, and that /dpa/ lists Anthropic."
  pause

  stage "Day 0: the notice email"
  say "The notice goes once to the owner of every organization, on every plan, and each send"
  say "is recorded. The first send starts the Assistant's 30 days. A re-run skips every owner"
  say "who already has it, so run this stage again to retry a failed send."
  if ! aws sesv2 get-email-template --template-name flexi-day-subprocessor-notice-prod \
    --region eu-central-1 >/dev/null 2>&1; then
    warn "flexi-day-subprocessor-notice-prod is not in SES; merge flexi-day-emails first."
    skip "the notice email (no prod template)"
    pause
    finish
    return 0
  fi
  if ! PROD_DATABASE="$(notice_env_url)"; then
    skip "the notice email (could not read the production database URL)"
    pause
    finish
    return 0
  fi
  say "The recipients, from the production database. Nothing is sent yet:"
  if ! subprocessor_notice --dry-run; then
    skip "the notice email (the dry run failed)"
    pause
    finish
    return 0
  fi
  if confirm "Send the notice to the owners listed as \"would send\"?"; then
    subprocessor_notice --send || notice_status=$?
    if ((notice_status != 0)); then
      warn "Some sends failed. Re-run this stage to retry them."
      SKIPPED+=("the notice email to the owners whose send failed")
    fi
    step "Put the \"First notice sent\" time on the launch task. Day 30 counts from it."
  else
    skip "the notice email"
  fi
  PROD_DATABASE=""
  pause

  stage "Day 0: the banner and AI connections"
  say "Before this flip:"
  step "The pages from the first stage are live."
  step "The notice email has gone to every owner, and its send time is on the launch task."
  say "privacy_banner_from shows every user the Privacy banner for 30 days from $day0,"
  say "but only once AI connections is on."
  note "privacy_banner_from is now $(current_tfvar privacy_banner_from)."
  note "ai_connections_enabled is now $(current_tfvar ai_connections_enabled)."
  if confirm "All of that is done. Set privacy_banner_from = \"$day0\" and ai_connections_enabled = true?"; then
    write_tfvar privacy_banner_from "\"$day0\""
    write_tfvar ai_connections_enabled true
    tf_apply "$TF_DIR" "the backend (flexi-day-be)"
  else
    skip "privacy_banner_from = \"$day0\" and ai_connections_enabled = true"
  fi
  pause

  stage "Day 30: the Assistant"
  say "The Assistant turns on no earlier than 30 days after the notice was sent, and"
  say "only with a passing eval baseline on main."
  ask sent_at "The day the notice was sent (YYYY-MM-DD), or Enter to stop here:" || true
  if [[ ! "$sent_at" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then
    skip "assistant_enabled = true (no notice date)"
    finish
    return 0
  fi
  sent_epoch="$(date -j -f %Y-%m-%d "$sent_at" +%s 2>/dev/null ||
    date -d "$sent_at" +%s 2>/dev/null || true)"
  if [[ -z "$sent_epoch" ]]; then
    skip "assistant_enabled = true (\"$sent_at\" is not a date)"
    finish
    return 0
  fi
  now_epoch="$(date +%s)"
  days=$(((now_epoch - sent_epoch) / 86400))
  if ((days < 30)); then
    warn "Only $days days since the notice. Come back in $((30 - days)) days."
    SKIPPED+=("assistant_enabled = true (day $days of 30)")
    pause
    finish
    return 0
  fi
  say "$days days since the notice."
  open_url "https://github.com/$REPO/actions"
  step "Check that the latest eval baseline on main passed."
  note "assistant_enabled is now $(current_tfvar assistant_enabled)."
  if confirm "The baseline passed. Set assistant_enabled = true?"; then
    write_tfvar assistant_enabled true
    tf_apply "$TF_DIR" "the backend (flexi-day-be)"
  else
    skip "assistant_enabled = true"
  fi
  pause
  finish
}

usage() {
  echo "usage: $0 dev|eval|prod|required-check|launch" >&2
  echo "Runbook: docs/terraform.md, \"Assistant and AI connections\"." >&2
  exit 2
}

run_wizard() {
  case "${1:-}" in
    dev) stages_dev ;;
    eval) stages_eval ;;
    prod) stages_prod ;;
    required-check) stages_required_check ;;
    launch) stages_launch ;;
    *) usage ;;
  esac
}

run_wizard "$@"; exit
